group extract_load_t_date_clin_ev(source answer, source src : QuestionnaireResponse, target bundle : Bundle) {
  src -> bundle.entry as entry then {
    src -> entry.request as req then {
      src -> req.method = 'POST' "method";
      src -> req.url = 'Observation' "url";
    } "req";
    src -> entry.resource = create('Observation') as tgt then {
      src.subject as subject -> tgt.subject = subject "subject";
      src.encounter as enc -> tgt.encounter = enc "encounter";
      src -> tgt.status = 'final' "status";
      src -> tgt.code = cc('http://example.com/fhir/CodeSystem/tricc', 't_date_clin_ev', 't_date_clin_ev') "code";
      src.authored as authored -> tgt.effective = authored "effective";
      answer.value : string as val -> tgt.value = val "value";
    } "resource";
  } "entry";
}

